    "owner.resetdb_confirm": "⚠️ *𝗖𝗢𝗡𝗙𝗜𝗥𝗠𝗔𝗖𝗜Ó𝗡 𝗗𝗘 𝗥𝗘𝗜𝗡𝗜𝗖𝗜𝗢 𝗗𝗘 𝗕𝗔𝗦𝗘 𝗗𝗘 𝗗𝗔𝗧𝗢𝗦*\n\n𝗔𝗿𝗰𝗵𝗶𝘃𝗼: {{file}}\n𝗠𝗼𝗱𝗼: {{mode}}\n\n𝗦𝗲 𝗰𝗿𝗲𝗮𝗿𝗮 𝘂𝗻𝗮 𝗰𝗼𝗽𝗶𝗮 𝗱𝗲 𝘀𝗲𝗴𝘂𝗿𝗶𝗱𝗮𝗱 𝗮𝗻𝘁𝗲𝘀 𝗱𝗲 𝗰𝗮𝗺𝗯𝗶𝗮𝗿 𝘂𝗻 𝗮𝗿𝗰𝗵𝗶𝘃𝗼 𝗲𝘅𝗶𝘀𝘁𝗲𝗻𝘁𝗲.\n\n𝗥𝗲𝘀𝗽𝗼𝗻𝗱𝗲 𝗲𝘅𝗮𝗰𝘁𝗮𝗺𝗲𝗻𝘁𝗲 *𝗖𝗢𝗡𝗙𝗜𝗥𝗠 𝗥𝗘𝗦𝗘𝗧* 𝗽𝗮𝗿𝗮 𝗰𝗼𝗻𝘁𝗶𝗻𝘂𝗮𝗿, 𝗼 *𝗖𝗔𝗡𝗖𝗘𝗟* 𝗽𝗮𝗿𝗮 𝗰𝗮𝗻𝗰𝗲𝗹𝗮𝗿.\n𝗘𝘀𝘁𝗮 𝗰𝗼𝗻𝗳𝗶𝗿𝗺𝗮𝗰𝗶𝗼𝗻 𝗲𝘅𝗽𝗶𝗿𝗮 𝗲𝗻 𝟔𝟎 𝘀𝗲𝗴𝘂𝗻𝗱𝗼𝘀.",
    "owner.resetdb_expired": "⏳ 𝗟𝗮 𝗰𝗼𝗻𝗳𝗶𝗿𝗺𝗮𝗰𝗶𝗼𝗻 𝗱𝗲 𝗿𝗲𝗶𝗻𝗶𝗰𝗶𝗼 𝗲𝘅𝗽𝗶𝗿𝗼. 𝗡𝗼 𝘀𝗲 𝗰𝗮𝗺𝗯𝗶𝗼 𝗻𝗮𝗱𝗮. 𝗘𝗷𝗲𝗰𝘂𝘁𝗮 .resetdb de 𝗻𝘂𝗲𝘃𝗼.",
