    "owner.resetdb_no_backup": "𝗡𝗼 𝗲𝘅𝗶𝘀𝘁𝗶𝗮 𝘂𝗻 𝗮𝗿𝗰𝗵𝗶𝘃𝗼 𝗽𝗿𝗲𝘃𝗶𝗼; 𝗻𝗼 𝘀𝗲 𝗻𝗲𝗰𝗲𝘀𝗶𝘁𝗼 𝗰𝗼𝗽𝗶𝗮 𝗱𝗲 𝘀𝗲𝗴𝘂𝗿𝗶𝗱𝗮𝗱.",
